import 'package:cloud_firestore/cloud_firestore.dart';

class FirestoreService {
  final FirebaseFirestore _db = FirebaseFirestore.instance;

  // ===== CREATE: 도큐먼트 생성 =====

  // 자동 ID로 생성
  Future<String> addUser(Map<String, dynamic> userData) async {
    final docRef = await _db.collection('users').add({
      ...userData,
      'createdAt': FieldValue.serverTimestamp(),
    });
    return docRef.id; // 생성된 도큐먼트 ID 반환
  }

  // 지정 ID로 생성/덮어쓰기
  Future<void> setUser(String userId, Map<String, dynamic> userData) async {
    await _db.collection('users').doc(userId).set({
      ...userData,
      'updatedAt': FieldValue.serverTimestamp(),
    });
  }

  // ===== READ: 도큐먼트 읽기 =====

  // 단일 도큐먼트 읽기 (1회성)
  Future<Map<String, dynamic>?> getUser(String userId) async {
    final doc = await _db.collection('users').doc(userId).get();
    if (doc.exists) {
      return {'id': doc.id, ...doc.data()!};
    }
    return null;
  }

  // 컬렉션 전체 읽기 (1회성)
  Future<List<Map<String, dynamic>>> getAllUsers() async {
    final snapshot = await _db.collection('users').get();
    return snapshot.docs.map((doc) {
      return {'id': doc.id, ...doc.data()};
    }).toList();
  }

  // ===== UPDATE: 도큐먼트 수정 =====

  // 특정 필드만 수정 (나머지 유지)
  Future<void> updateUser(String userId, Map<String, dynamic> data) async {
    await _db.collection('users').doc(userId).update({
      ...data,
      'updatedAt': FieldValue.serverTimestamp(),
    });
  }

  // 배열에 항목 추가
  Future<void> addToFavorites(String userId, String itemId) async {
    await _db.collection('users').doc(userId).update({
      'favorites': FieldValue.arrayUnion([itemId]),
    });
  }

  // 숫자 증가
  Future<void> incrementLikes(String postId) async {
    await _db.collection('posts').doc(postId).update({
      'likes': FieldValue.increment(1),
    });
  }

  // ===== DELETE: 도큐먼트 삭제 =====

  Future<void> deleteUser(String userId) async {
    await _db.collection('users').doc(userId).delete();
  }

  // 특정 필드만 삭제
  Future<void> removeField(String userId, String fieldName) async {
    await _db.collection('users').doc(userId).update({
      fieldName: FieldValue.delete(),
    });
  }
}

import 'package:flutter/material.dart';
import 'package:cloud_firestore/cloud_firestore.dart';

class UsersScreen extends StatelessWidget {
  const UsersScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('사용자 목록')),
      body: StreamBuilder<QuerySnapshot>(
        // 실시간 스트림 구독
        stream: FirebaseFirestore.instance
            .collection('users')
            .orderBy('createdAt', descending: true)
            .snapshots(),
        builder: (context, snapshot) {
          // 에러 처리
          if (snapshot.hasError) {
            return Center(child: Text('에러: ${snapshot.error}'));
          }

          // 로딩 상태
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          // 데이터가 없는 경우
          final docs = snapshot.data?.docs ?? [];
          if (docs.isEmpty) {
            return const Center(child: Text('사용자가 없습니다'));
          }

          // 데이터 표시
          return ListView.builder(
            itemCount: docs.length,
            itemBuilder: (context, index) {
              final doc = docs[index];
              final data = doc.data() as Map<String, dynamic>;

              return ListTile(
                leading: CircleAvatar(
                  child: Text(data['name']?[0] ?? '?'),
                ),
                title: Text(data['name'] ?? '이름 없음'),
                subtitle: Text(data['email'] ?? ''),
                trailing: IconButton(
                  icon: const Icon(Icons.delete),
                  onPressed: () => doc.reference.delete(),
                ),
              );
            },
          );
        },
      ),
    );
  }
}

// 단일 도큐먼트 실시간 감시
class UserDetailScreen extends StatelessWidget {
  final String userId;
  const UserDetailScreen({super.key, required this.userId});

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<DocumentSnapshot>(
      stream: FirebaseFirestore.instance
          .collection('users')
          .doc(userId)
          .snapshots(),
      builder: (context, snapshot) {
        if (!snapshot.hasData) {
          return const Center(child: CircularProgressIndicator());
        }

        final data = snapshot.data!.data() as Map<String, dynamic>?;
        if (data == null) {
          return const Center(child: Text('사용자를 찾을 수 없습니다'));
        }

        return Padding(
          padding: const EdgeInsets.all(16),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text('이름: ${data['name']}', style: const TextStyle(fontSize: 24)),
              Text('이메일: ${data['email']}'),
              Text('가입일: ${data['createdAt']?.toDate()}'),
            ],
          ),
        );
      },
    );
  }
}

import 'package:cloud_firestore/cloud_firestore.dart';

class QueryExamples {
  final _db = FirebaseFirestore.instance;

  // 단일 조건 필터
  Future<List<QueryDocumentSnapshot>> getActiveUsers() async {
    final snapshot = await _db
        .collection('users')
        .where('isActive', isEqualTo: true)
        .get();
    return snapshot.docs;
  }

  // 복합 조건 (AND)
  Future<List<QueryDocumentSnapshot>> getAdultActiveUsers() async {
    final snapshot = await _db
        .collection('users')
        .where('isActive', isEqualTo: true)
        .where('age', isGreaterThanOrEqualTo: 18)
        .get();
    return snapshot.docs;
  }

  // 범위 쿼리
  Future<List<QueryDocumentSnapshot>> getUsersByAgeRange(
    int minAge, int maxAge,
  ) async {
    final snapshot = await _db
        .collection('users')
        .where('age', isGreaterThanOrEqualTo: minAge)
        .where('age', isLessThan: maxAge)
        .orderBy('age')
        .get();
    return snapshot.docs;
  }

  // 배열 포함 여부
  Future<List<QueryDocumentSnapshot>> getUsersWithTag(String tag) async {
    final snapshot = await _db
        .collection('users')
        .where('tags', arrayContains: tag)
        .get();
    return snapshot.docs;
  }

  // 여러 값 중 하나 일치 (OR 효과)
  Future<List<QueryDocumentSnapshot>> getUsersByStatus(
    List<String> statuses,
  ) async {
    final snapshot = await _db
        .collection('users')
        .where('status', whereIn: statuses)  // 최대 10개
        .get();
    return snapshot.docs;
  }

  // 정렬과 제한
  Future<List<QueryDocumentSnapshot>> getRecentUsers(int limit) async {
    final snapshot = await _db
        .collection('users')
        .orderBy('createdAt', descending: true)
        .limit(limit)
        .get();
    return snapshot.docs;
  }

  // 페이지네이션 (커서 기반)
  Future<List<QueryDocumentSnapshot>> getNextPage(
    DocumentSnapshot? lastDoc,
    int pageSize,
  ) async {
    Query query = _db
        .collection('users')
        .orderBy('createdAt', descending: true)
        .limit(pageSize);

    // 마지막 도큐먼트 이후부터
    if (lastDoc != null) {
      query = query.startAfterDocument(lastDoc);
    }

    final snapshot = await query.get();
    return snapshot.docs;
  }

  // 복합 인덱스 필요 쿼리 (다른 필드로 where + orderBy)
  Future<List<QueryDocumentSnapshot>> getActiveUsersByDate() async {
    // Firebase Console에서 복합 인덱스 생성 필요!
    final snapshot = await _db
        .collection('users')
        .where('isActive', isEqualTo: true)
        .orderBy('createdAt', descending: true)
        .get();
    return snapshot.docs;
  }
}

import 'package:cloud_firestore/cloud_firestore.dart';

class UserModel {
  final String id;
  final String name;
  final String email;
  final int age;
  final bool isActive;
  final List<String> tags;
  final DateTime? createdAt;

  UserModel({
    required this.id,
    required this.name,
    required this.email,
    required this.age,
    this.isActive = true,
    this.tags = const [],
    this.createdAt,
  });

  // Firestore 도큐먼트에서 모델 생성
  factory UserModel.fromFirestore(DocumentSnapshot doc) {
    final data = doc.data() as Map<String, dynamic>;
    return UserModel(
      id: doc.id,
      name: data['name'] ?? '',
      email: data['email'] ?? '',
      age: data['age'] ?? 0,
      isActive: data['isActive'] ?? true,
      tags: List<String>.from(data['tags'] ?? []),
      createdAt: (data['createdAt'] as Timestamp?)?.toDate(),
    );
  }

  // 모델을 Firestore 데이터로 변환
  Map<String, dynamic> toFirestore() {
    return {
      'name': name,
      'email': email,
      'age': age,
      'isActive': isActive,
      'tags': tags,
      'createdAt': createdAt != null 
          ? Timestamp.fromDate(createdAt!) 
          : FieldValue.serverTimestamp(),
    };
  }

  // copyWith 패턴
  UserModel copyWith({
    String? name,
    String? email,
    int? age,
    bool? isActive,
    List<String>? tags,
  }) {
    return UserModel(
      id: id,
      name: name ?? this.name,
      email: email ?? this.email,
      age: age ?? this.age,
      isActive: isActive ?? this.isActive,
      tags: tags ?? this.tags,
      createdAt: createdAt,
    );
  }
}

// withConverter를 사용한 타입 안전 컬렉션
class TypedFirestoreService {
  // 타입 변환기가 적용된 컬렉션 참조
  final CollectionReference<UserModel> usersRef = 
      FirebaseFirestore.instance
          .collection('users')
          .withConverter<UserModel>(
            fromFirestore: (snapshot, _) => UserModel.fromFirestore(snapshot),
            toFirestore: (user, _) => user.toFirestore(),
          );

  // 이제 타입 안전하게 사용 가능!
  Future<void> addUser(UserModel user) async {
    await usersRef.add(user);  // UserModel 직접 전달
  }

  Future<UserModel?> getUser(String id) async {
    final doc = await usersRef.doc(id).get();
    return doc.data();  // UserModel? 반환
  }

  Stream<List<UserModel>> watchUsers() {
    return usersRef.snapshots().map((snapshot) {
      return snapshot.docs.map((doc) => doc.data()).toList();
    });
  }
}

